create schema if not exists chatten_cafe;
create extension if not exists pgcrypto;

create or replace function chatten_cafe.set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at = now(); return new; end $$;
create table if not exists chatten_cafe.site_settings (id uuid primary key default gen_random_uuid(), site_name text not null, tagline text, description text, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists chatten_cafe.hero_slides (id uuid primary key default gen_random_uuid(), title text not null, subtitle text, image_media_id uuid, cta_label text, cta_url text, sort_order integer not null default 0, is_active boolean not null default true, status text not null default 'draft' check (status in ('draft','published')), published_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists chatten_cafe.moments (id uuid primary key default gen_random_uuid(), name text not null unique, description text, image_media_id uuid, sort_order integer not null default 0, is_active boolean not null default true, status text not null default 'draft' check (status in ('draft','published')), published_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists chatten_cafe.about_sections (id uuid primary key default gen_random_uuid(), title text not null, body text not null, image_media_id uuid, sort_order integer not null default 0, is_active boolean not null default true, status text not null default 'draft' check (status in ('draft','published')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists chatten_cafe.experiences (id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique, description text not null, image_media_id uuid, sort_order integer not null default 0, is_active boolean not null default true, status text not null default 'draft' check (status in ('draft','published')), published_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists chatten_cafe.spaces (id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique, description text, image_media_id uuid, sort_order integer not null default 0, is_active boolean not null default true, status text not null default 'draft' check (status in ('draft','published')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists chatten_cafe.menu_categories (id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique, description text, sort_order integer not null default 0, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists chatten_cafe.menu_items (id uuid primary key default gen_random_uuid(), category_id uuid not null references chatten_cafe.menu_categories(id) on delete restrict, name text not null, slug text not null unique, description text, price numeric(10,2) check (price is null or price >= 0), image_media_id uuid, sort_order integer not null default 0, is_active boolean not null default true, status text not null default 'draft' check (status in ('draft','published')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists chatten_cafe.gallery_items (id uuid primary key default gen_random_uuid(), title text, image_media_id uuid, alt_text text not null, sort_order integer not null default 0, is_active boolean not null default true, status text not null default 'draft' check (status in ('draft','published')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists chatten_cafe.testimonials (id uuid primary key default gen_random_uuid(), author_name text not null, quote text not null, source text, sort_order integer not null default 0, is_active boolean not null default true, status text not null default 'draft' check (status in ('draft','published')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists chatten_cafe.promotions (id uuid primary key default gen_random_uuid(), title text not null, slug text not null unique, summary text, body text, image_media_id uuid, starts_at timestamptz, ends_at timestamptz, is_active boolean not null default true, status text not null default 'draft' check (status in ('draft','published')), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check (ends_at is null or starts_at is null or ends_at >= starts_at));
create table if not exists chatten_cafe.events (id uuid primary key default gen_random_uuid(), title text not null, slug text not null unique, summary text, body text, image_media_id uuid, starts_at timestamptz not null, ends_at timestamptz, is_active boolean not null default true, status text not null default 'draft' check (status in ('draft','published')), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check (ends_at is null or ends_at >= starts_at));
create table if not exists chatten_cafe.opening_hours (id uuid primary key default gen_random_uuid(), day_of_week smallint not null check (day_of_week between 0 and 6), opens_at time, closes_at time, is_closed boolean not null default false, sort_order integer not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(day_of_week, sort_order));
create table if not exists chatten_cafe.contact_information (id uuid primary key default gen_random_uuid(), address text, phone text, whatsapp_url text, email text, map_url text, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists chatten_cafe.social_links (id uuid primary key default gen_random_uuid(), platform text not null, label text, url text not null, sort_order integer not null default 0, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists chatten_cafe.navigation_items (id uuid primary key default gen_random_uuid(), label text not null, href text not null, sort_order integer not null default 0, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists chatten_cafe.media (id uuid primary key default gen_random_uuid(), bucket text not null, storage_path text not null, original_filename text not null, mime_type text not null, file_size bigint, width integer, height integer, alt_text text, uploaded_by uuid references auth.users(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(bucket, storage_path));
create table if not exists chatten_cafe.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists chatten_cafe.user_roles (user_id uuid primary key references chatten_cafe.profiles(id) on delete cascade, role text not null check (role in ('super_admin','admin','editor')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists chatten_cafe.seo_settings (id uuid primary key default gen_random_uuid(), page_key text not null unique, title text, description text, canonical_url text, og_media_id uuid, robots text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());

create or replace function chatten_cafe.handle_new_user() returns trigger language plpgsql security definer set search_path = chatten_cafe, public as $$ begin insert into chatten_cafe.profiles(id) values (new.id) on conflict do nothing; return new; end $$;
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure chatten_cafe.handle_new_user();
do $$ declare t text; begin foreach t in array array['site_settings','hero_slides','moments','about_sections','experiences','spaces','menu_categories','menu_items','gallery_items','testimonials','promotions','events','opening_hours','contact_information','social_links','navigation_items','media','profiles','user_roles','seo_settings'] loop execute format('drop trigger if exists set_updated_at on chatten_cafe.%I; create trigger set_updated_at before update on chatten_cafe.%I for each row execute procedure chatten_cafe.set_updated_at()',t,t); end loop; end $$;
create or replace function chatten_cafe.has_role(required_role text) returns boolean language sql stable security definer set search_path = chatten_cafe, public as $$ select exists(select 1 from chatten_cafe.user_roles where user_id = auth.uid() and (role = required_role or role = 'super_admin' or (required_role = 'editor' and role = 'admin'))) $$;
grant usage on schema chatten_cafe to anon, authenticated;
grant select on all tables in schema chatten_cafe to anon, authenticated;
grant insert, update, delete on all tables in schema chatten_cafe to authenticated;
grant execute on function chatten_cafe.has_role(text) to anon, authenticated;
do $$ declare t text; begin foreach t in array array['site_settings','hero_slides','moments','about_sections','experiences','spaces','menu_categories','menu_items','gallery_items','testimonials','promotions','events','opening_hours','contact_information','social_links','navigation_items','media','profiles','user_roles','seo_settings'] loop execute format('alter table chatten_cafe.%I enable row level security',t); end loop; end $$;
do $$ declare policy_record record; begin for policy_record in select tablename, policyname from pg_policies where schemaname = 'chatten_cafe' loop execute format('drop policy if exists %I on chatten_cafe.%I', policy_record.policyname, policy_record.tablename); end loop; end $$;
create policy public_site on chatten_cafe.site_settings for select using (is_active);
create policy public_content on chatten_cafe.hero_slides for select using (is_active and status = 'published');
create policy public_content on chatten_cafe.moments for select using (is_active and status = 'published');
create policy public_content on chatten_cafe.about_sections for select using (is_active and status = 'published');
create policy public_content on chatten_cafe.experiences for select using (is_active and status = 'published');
create policy public_content on chatten_cafe.spaces for select using (is_active and status = 'published');
create policy public_content on chatten_cafe.menu_categories for select using (is_active);
create policy public_content on chatten_cafe.menu_items for select using (is_active and status = 'published');
create policy public_content on chatten_cafe.gallery_items for select using (is_active and status = 'published');
create policy public_content on chatten_cafe.testimonials for select using (is_active and status = 'published');
create policy public_content on chatten_cafe.promotions for select using (is_active and status = 'published');
create policy public_content on chatten_cafe.events for select using (is_active and status = 'published');
create policy public_content on chatten_cafe.opening_hours for select using (true);
create policy public_site on chatten_cafe.contact_information for select using (is_active);
create policy public_content on chatten_cafe.social_links for select using (is_active);
create policy public_content on chatten_cafe.navigation_items for select using (is_active);
create policy public_content on chatten_cafe.seo_settings for select using (true);
create policy own_profile on chatten_cafe.profiles for select using (id = auth.uid());
create policy cms_manage on chatten_cafe.site_settings for all to authenticated using (chatten_cafe.has_role('editor')) with check (chatten_cafe.has_role('editor'));
do $$ declare t text; begin foreach t in array array['hero_slides','moments','about_sections','experiences','spaces','menu_categories','menu_items','gallery_items','testimonials','promotions','events','opening_hours','contact_information','social_links','navigation_items','media','seo_settings'] loop execute format('create policy cms_manage on chatten_cafe.%I for all to authenticated using (chatten_cafe.has_role(%L)) with check (chatten_cafe.has_role(%L))', t, 'editor', 'editor'); end loop; end $$;
create policy profile_manage on chatten_cafe.profiles for update to authenticated using (id = auth.uid() or chatten_cafe.has_role('admin')) with check (id = auth.uid() or chatten_cafe.has_role('admin'));
create policy role_manage on chatten_cafe.user_roles for all to authenticated using (chatten_cafe.has_role('admin')) with check (chatten_cafe.has_role('admin'));
insert into storage.buckets (id, name, public) values ('chatten-media', 'chatten-media', true) on conflict (id) do update set public = excluded.public;
drop policy if exists "chatten public read" on storage.objects;
drop policy if exists "chatten cms manage" on storage.objects;
create policy "chatten public read" on storage.objects for select using (bucket_id = 'chatten-media');
create policy "chatten cms manage" on storage.objects for all to authenticated using (bucket_id = 'chatten-media' and chatten_cafe.has_role('editor')) with check (bucket_id = 'chatten-media' and chatten_cafe.has_role('editor'));
